from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit
import hashlib, json, re

source_url = 'https://jobs.wordpress.net/'
source = Path('products/services/wordpress-migration-paid-qa/raw/wordpress-jobs-index.html')
raw = source.read_bytes()
expected_hash = '68f52f538fec9448f7af470f591834b310d198d73c2a46c44e483a96f030e1ec'
assert hashlib.sha256(raw).hexdigest() == expected_hash, 'Index bytes differ from the recorded FETCH receipt'

class JobLinks(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.current = None
        self.links = {}

    def handle_starttag(self, tag, attrs):
        if tag != 'a':
            return
        self.current = None
        url = urljoin(source_url, dict(attrs).get('href') or '')
        parts = urlsplit(url)
        if parts.scheme == 'https' and parts.netloc == 'jobs.wordpress.net' and re.fullmatch(r'/job/[^/]+/?', parts.path):
            self.current = (source_url.rstrip('/') + parts.path, [])

    def handle_data(self, data):
        if self.current is not None:
            self.current[1].append(data)

    def handle_endtag(self, tag):
        if tag == 'a' and self.current is not None:
            url, fragments = self.current
            title = ' '.join(''.join(fragments).split())
            if title:
                self.links.setdefault(url, title)
            self.current = None

parser = JobLinks()
parser.feed(raw.decode('utf-8'))
keywords = re.compile(r'\b(migrat\w*|import\w*|export\w*|content transfer|catalog(?:ue)?|woocommerce)\b', re.I)
pointers = [{'url': url, 'index_title': title} for url, title in parser.links.items() if keywords.search(title + ' ' + url.replace('-', ' '))]
result = {'source_url': source_url, 'source_receipt': 'TASK-179541722200', 'source_sha256': expected_hash, 'recognized_listing_links': len(parser.links), 'pointers': pointers, 'coverage': 'Single saved index. Same-site /job/ links screened by index title and URL only. Zero recognized links would indicate an extraction or coverage gap. A match still requires original-listing verification of current scope, paid terms and application route.'}
output = source.parent.parent / 'director-index-pointers.json'
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
